// ─── File: src/main/java/com/bank/access/model/Account.java ───
package com.bank.access.model;

import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private BigDecimal balance;

    public Account(String accountId, BigDecimal balance) {
        this.accountId = accountId;
        this.balance = balance;
    }

    // PRIVATE: not inherited → not overridable
    private void auditInternal() {
        System.out.println("Account internal audit");
    }

    // DEFAULT (package-private): overridable with same or wider
    void reconcile() {
        System.out.println("Account reconcile (default access)");
    }

    // PROTECTED: overridable with same or wider (protected/public)
    protected void validate() {
        if (balance.signum() < 0) throw new IllegalStateException("Negative balance!");
    }

    // PUBLIC: overridable with same only (public is the widest)
    public BigDecimal calculateFee() {
        return BigDecimal.ZERO;
    }

    // FINAL: CANNOT be overridden — sealed
    public final String getAccountId() { return accountId; }

    // STATIC: hidden, NOT overridden
    public static String getPolicy() { return "Standard Banking Policy"; }

    public BigDecimal getBalance() { return balance; }
    protected void setBalance(BigDecimal balance) { this.balance = balance; }

    // For testing private method existence:
    public String callAudit() { auditInternal(); return "audit called"; }
}
```

