// ─── File: src/main/java/com/bank/access/model/SavingsAccount.java ───
package com.bank.access.model;

import java.math.BigDecimal;

public class SavingsAccount extends Account {

    public SavingsAccount(String accountId, BigDecimal balance) {
        super(accountId, balance);
    }

    // ═══ DEFAULT → PROTECTED: widen ✅ ═══
    @Override
    protected void reconcile() {  // default → protected: WIDER ✅
        System.out.println("Savings reconcile (protected — widened from default)");
    }

    // ═══ PROTECTED → PUBLIC: widen ✅ ═══
    @Override
    public void validate() {  // protected → public: WIDER ✅
        super.validate();
        if (getBalance().compareTo(new BigDecimal("1000")) < 0) {
            throw new IllegalStateException("Savings minimum balance Rs.1000!");
        }
    }

    // ═══ PUBLIC → PUBLIC: same ✅ ═══
    @Override
    public BigDecimal calculateFee() {  // public → public: SAME ✅
        return getBalance().multiply(new BigDecimal("0.001"));
    }

    // ═══ STATIC: hidden (NOT overridden) ═══
    public static String getPolicy() { return "Savings Special Policy"; }

    // ═══ FINAL: cannot override getAccountId() ═══
    // @Override public String getAccountId() { return "FAKE"; }  // ❌ COMPILE ERROR!

    // ═══ PRIVATE: cannot override auditInternal() — it's NOT inherited ═══
    // This is a NEW method, not an override:
    private void auditInternal() {
        System.out.println("Savings own audit — NOT an override of Account.auditInternal()");
    }
}
