```java
// ─── File: src/test/java/com/bank/access/AccessModifierRulesTest.java ───
package com.bank.access;

import com.bank.access.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class AccessModifierRulesTest {

    // ═══ WIDEN: protected → public ═══
    @Test
    void widenProtectedToPublic() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("5000"));
        sa.validate();  // PUBLIC — callable from anywhere!
        // Parent's validate() was protected — child widened to public ✅
    }

    // ═══ SAME: public → public ═══
    @Test
    void samePublicToPublic() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("5000"));
        BigDecimal fee = sa.calculateFee();  // public → public ✅
        assertThat(fee).isEqualByComparingTo("5");  // 5000 × 0.1%
    }

    // ═══ FINAL: cannot override ═══
    @Test
    void finalCannotBeOverridden() {
        Account account = new SavingsAccount("SAV001", BigDecimal.ZERO);
        assertThat(account.getAccountId()).isEqualTo("SAV001");
        // getAccountId() is final — SavingsAccount CANNOT override it.
        // Even if SavingsAccount tried to return "FAKE", it would NOT compile.
    }

    // ═══ STATIC: hidden, NOT overridden ═══
    @Test
    void staticIsHiddenNotOverridden() {
        // Through class names — different results (hiding):
        assertThat(Account.getPolicy()).isEqualTo("Standard Banking Policy");
        assertThat(SavingsAccount.getPolicy()).isEqualTo("Savings Special Policy");

        // Through PARENT reference — proves NOT overridden:
        Account ref = new SavingsAccount("SAV001", BigDecimal.ZERO);
        assertThat(ref.getPolicy()).isEqualTo("Standard Banking Policy");
        // ↑ If this were a true override, would return "Savings Special Policy"
        // But static binds at compile time to variable type (Account) → NOT overridden!
    }

    // ═══ PRIVATE: not inherited, not overridable ═══
    @Test
    void privateNotInherited() {
        Account account = new Account("ACC001", BigDecimal.ZERO);
        account.callAudit();  // calls Account.auditInternal() — private, accessible only inside Account

        SavingsAccount sa = new SavingsAccount("SAV001", BigDecimal.ZERO);
        // sa.auditInternal();  // WON'T COMPILE — private in SavingsAccount (different method!)
        // SavingsAccount has its OWN auditInternal() — NOT an override of Account's.
    }

    // ═══ LISKOV: child substitutable for parent ═══
    @Test
    void liskovSubstitution_widerAccessWorks() {
        // Code expects Account:
        Account account = new SavingsAccount("SAV001", new BigDecimal("5000"));
        account.validate();  // protected on Account → public on SavingsAccount → works!
        // If SavingsAccount had NARROWED to private: this call would fail. Liskov violated.
    }

    // ═══ COMPREHENSIVE: all modifiers in one test ═══
    @Test
    void allModifierRulesSummary() {
        // private:   NOT inherited → cannot override (child's same-name method is NEW)
        // default:   CAN override with default, protected, or public (widen)
        // protected: CAN override with protected or public (widen)
        // public:    CAN override with public ONLY (it's the widest)
        // final:     CANNOT override — sealed
        // static:    CANNOT override — hidden (compile-time binding to class)

        assertThat(true).isTrue();
    }
}
```
